// @vitest-environment jsdom
/** The existing authoring filer must confirm its own receipt and retain uncertain writes. */
import React from 'react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';

const apiRequest = vi.hoisted(() => vi.fn());
vi.mock('@/lib/queryClient', async original => ({ ...(await original<typeof import('@/lib/queryClient')>()), apiRequest }));
import { ApiRequestError } from '@/lib/queryClient';
import { authService } from '@/services/portal/authService';
import { FileToVaultDialog, type FileToVaultDialogProps } from '../editor/FileToVaultDialog';
import { publishShellProject } from '../shellProject';
import { DOC_ID, PID } from './_vault-surface-fixtures';
import { deferred } from './_submission-deliverables-fixture';

const SOURCE = '33333333-3333-4333-8333-333333333333';
const OTHER = '44444444-4444-4444-8444-444444444444';
const receipt = (changes: Record<string, unknown> = {}) => ({ success: true, data: {
  vaultDocumentId: DOC_ID, programId: PID, sha256: 'a'.repeat(64), format: 'pdf', folder: 'module-3', ...changes,
} });
const response = (body: unknown, status = 201) => new Response(JSON.stringify(body), { status });
const props = (): FileToVaultDialogProps => ({
  docId: SOURCE, docTitle: 'Stability summary', docStatus: 'APPROVED', programId: PID,
  programName: 'BX-301', onClose: vi.fn(), onFiled: vi.fn(), onNav: vi.fn(), fireToast: vi.fn(),
});
const submit = () => fireEvent.click(screen.getByTestId('ftv-submit'));

beforeEach(() => {
  authService.setToken('fixture-vault-author-a', { id: '7', organizationId: '1' }, 'fixture-vault-refresh', 3600);
  publishShellProject({ id: PID, title: 'BX-301' });
  apiRequest.mockReset().mockImplementation(async () => response(receipt()));
});
afterEach(() => {
  cleanup(); authService.endSession(null);
  delete window.C2C_PROJECT; delete window.C2C_VAULT_TARGET;
  vi.unstubAllGlobals();
});

describe('File to vault receipt confirmation', () => {
  it.each([
    ['non-UUID Vault identity', receipt({ vaultDocumentId: 'another-record' })],
    ['empty Vault identity', receipt({ vaultDocumentId: '' })],
    ['missing project', receipt({ programId: undefined })],
    ['another project', receipt({ programId: OTHER })],
    ['non-UUID project', receipt({ programId: 'project-1' })],
    ['missing content hash', receipt({ sha256: undefined })],
    ['short content hash', receipt({ sha256: 'a'.repeat(63) })],
    ['non-hex content hash', receipt({ sha256: 'g'.repeat(64) })],
    ['missing format', receipt({ format: undefined })],
    ['another requested format', receipt({ format: 'docx' })],
    ['unsupported format', receipt({ format: 'txt' })],
    ['version without predecessor metadata', receipt({ version: '2.0' })],
    ['predecessor without assigned version', receipt({ supersedesDocumentId: OTHER })],
    ['null assigned version', receipt({ version: null, supersedesDocumentId: null })],
    ['numeric assigned version', receipt({ version: 2, supersedesDocumentId: OTHER })],
    ['legacy hash version', receipt({ version: 'draft-12345678', supersedesDocumentId: null })],
    ['minor version', receipt({ version: '2.1', supersedesDocumentId: OTHER })],
    ['zero major version', receipt({ version: '0.0', supersedesDocumentId: null })],
    ['negative major version', receipt({ version: '-1.0', supersedesDocumentId: null })],
    ['leading-zero major version', receipt({ version: '02.0', supersedesDocumentId: OTHER })],
    ['unsafe major version', receipt({ version: '9007199254740992.0', supersedesDocumentId: OTHER })],
    ['malformed predecessor', receipt({ version: '2.0', supersedesDocumentId: 'another-record' })],
    ['empty predecessor', receipt({ version: '2.0', supersedesDocumentId: '' })],
    ['self predecessor', receipt({ version: '2.0', supersedesDocumentId: DOC_ID })],
    ['case-varied self predecessor', receipt({ version: '2.0', supersedesDocumentId: DOC_ID.toUpperCase() })],
    ['explicit false success', { ...receipt(), success: false }],
    ['contradictory error envelope', { ...receipt(), error: { message: 'The recording failed.' } }],
    ['missing record', { success: true, data: {} }],
  ])('holds a successful HTTP answer with %s for review without replay', async (_name, body) => {
    const p = props(); apiRequest.mockImplementation(async () => response(body));
    render(<FileToVaultDialog {...p} />); submit();
    const error = await screen.findByTestId('ftv-error');
    expect(error.textContent).toMatch(/cannot confirm.*filed/i);
    expect(error.textContent).toMatch(/check.*vault.*before retrying/i);
    expect(error.textContent).not.toContain('Nothing was written');
    expect(screen.queryByTestId('ftv-result')).toBeNull();
    expect(screen.queryByTestId('ftv-open-vault')).toBeNull();
    expect((screen.getByTestId('ftv-submit') as HTMLButtonElement).disabled).toBe(true);
    submit(); expect(apiRequest).toHaveBeenCalledTimes(1);
    expect(p.onFiled).not.toHaveBeenCalled(); expect(p.fireToast).not.toHaveBeenCalled();
  });

  it.each(['lost reply', 'unreadable body', 'bodyless 204', 'null body', 'HTTP 500', 'outcome unknown', 'existing version'] as const)(
    'holds %s through ordinary close and reopen', async kind => {
      apiRequest.mockImplementation(async () => {
        if (kind === 'lost reply') throw new Error('Failed to fetch');
        if (kind === 'unreadable body') return new Response('{', { status: 201 });
        if (kind === 'bodyless 204') return new Response(null, { status: 204 });
        if (kind === 'null body') return response(null);
        if (kind === 'HTTP 500') return response({ error: { message: 'The export did not finish.' } }, 500);
        const code = kind === 'existing version' ? 'VAULT_VERSION_ALREADY_RECORDED' : 'OUTCOME_UNKNOWN';
        throw new ApiRequestError('Check the existing Vault record before retrying.', 409, { error: { code } }, code);
      });
      const p = props(); const view = render(<FileToVaultDialog {...p} open />); submit();
      const error = await screen.findByTestId('ftv-error');
      expect(error.textContent).toMatch(/cannot confirm.*filed|existing.*vault/i);
      expect(error.textContent).not.toContain('Nothing was written');
      view.rerender(<FileToVaultDialog {...p} open={false} />);
      expect(screen.queryByTestId('file-to-vault-dialog')).toBeNull();
      view.rerender(<FileToVaultDialog {...p} open />);
      expect(screen.getByTestId('ftv-error').textContent).toBe(error.textContent);
      expect((screen.getByTestId('ftv-submit') as HTMLButtonElement).disabled).toBe(true);
      submit(); expect(apiRequest).toHaveBeenCalledTimes(1);
      expect(p.onFiled).not.toHaveBeenCalled(); expect(p.fireToast).not.toHaveBeenCalled();
    },
  );

  it.each([401, 403, 409, 422, 429])('retains a definite HTTP %s refusal and allows a deliberate retry', async status => {
    apiRequest.mockImplementationOnce(async () => response({ error: { message: 'This document cannot be filed in its current state.', code: 'FILING_REFUSED' } }, status));
    const p = props(); render(<FileToVaultDialog {...p} />); submit();
    expect((await screen.findByTestId('ftv-error')).textContent).toContain('This document cannot be filed');
    expect((screen.getByTestId('ftv-submit') as HTMLButtonElement).disabled).toBe(false);
    submit(); await screen.findByTestId('ftv-result');
    expect(apiRequest).toHaveBeenCalledTimes(2); expect(p.onFiled).toHaveBeenCalledTimes(1);
  });

  it('keeps the request project and UUID for navigation and never invents missing approval', async () => {
    const p = props(); render(<FileToVaultDialog {...p} />); submit();
    await screen.findByTestId('ftv-result');
    expect(apiRequest).toHaveBeenCalledWith('POST', `/api/authoring/docs/${SOURCE}/file-to-vault`, { format: 'pdf' });
    expect(screen.getByTestId('ftv-approval').textContent).toContain('did not report whether the approval carried');
    fireEvent.click(screen.getByTestId('ftv-open-vault'));
    expect(window.C2C_VAULT_TARGET).toEqual({ documentId: DOC_ID, programId: PID });
    expect(p.onNav).toHaveBeenCalledWith('vault');
  });

  it('keeps older data-envelope compatibility without inventing approval', async () => {
    apiRequest.mockImplementation(async () => response({ data: receipt().data, error: null }));
    const p = props(); render(<FileToVaultDialog {...p} />); submit();
    await screen.findByTestId('ftv-result');
    expect(screen.getByTestId('ftv-approval').textContent).toContain('did not report whether the approval carried');
    expect(screen.getByTestId('ftv-result').textContent).not.toContain('Vault version');
    expect(screen.getByTestId('ftv-result').textContent).not.toContain('Supersedes');
    expect(p.onFiled).toHaveBeenCalledWith(expect.not.objectContaining({ version: expect.anything() }));
    expect(p.onFiled).toHaveBeenCalledTimes(1);
  });

  it.each([
    ['1.0', null],
    ['4.0', OTHER],
  ])('retains the server-confirmed version %s and predecessor in the receipt callback', async (version, supersedesDocumentId) => {
    apiRequest.mockImplementation(async () => response(receipt({ version, supersedesDocumentId })));
    const p = props(); render(<FileToVaultDialog {...p} />); submit();
    await screen.findByTestId('ftv-result');
    expect(p.onFiled).toHaveBeenCalledWith(expect.objectContaining({ version, supersedesDocumentId }));
    expect(p.fireToast).toHaveBeenCalledTimes(1);
  });

  it('retains malformed lineage as an uncertain outcome across close and reopen', async () => {
    apiRequest.mockImplementation(async () => response(receipt({ version: '2.0', supersedesDocumentId: DOC_ID })));
    const p = props(); const view = render(<FileToVaultDialog {...p} open />); submit();
    const error = await screen.findByTestId('ftv-error');
    view.rerender(<FileToVaultDialog {...p} open={false} />);
    view.rerender(<FileToVaultDialog {...p} open />);
    expect(screen.getByTestId('ftv-error').textContent).toBe(error.textContent);
    expect(screen.getByTestId('ftv-submit')).toHaveProperty('disabled', true);
    submit(); expect(apiRequest).toHaveBeenCalledTimes(1);
    expect(p.onFiled).not.toHaveBeenCalled();
  });
});

describe('File to vault current request ownership', () => {
  it('does not file a retained document from another existing shell project', () => {
    publishShellProject({ id: OTHER, title: 'Another program' });
    const p = props(); render(<FileToVaultDialog {...p} />);
    expect((screen.getByTestId('ftv-submit') as HTMLButtonElement).disabled).toBe(true);
    submit(); expect(apiRequest).not.toHaveBeenCalled();
  });

  it('keeps the standalone dialog usable when no shell project is selected', async () => {
    delete window.C2C_PROJECT;
    const p = props(); render(<FileToVaultDialog {...p} />); submit();
    await screen.findByTestId('ftv-result');
    fireEvent.click(screen.getByTestId('ftv-open-vault'));
    expect(window.C2C_VAULT_TARGET).toEqual({ documentId: DOC_ID, programId: PID });
    expect(p.onNav).toHaveBeenCalledWith('vault');
  });

  it('does not toast in a context retired by the synchronous filing callback', async () => {
    const p = props(); p.onFiled = vi.fn(() => publishShellProject({ id: OTHER }));
    render(<FileToVaultDialog {...p} />); submit();
    await act(async () => {});
    expect(p.onFiled).toHaveBeenCalledTimes(1);
    expect(p.fireToast).not.toHaveBeenCalled();
  });

  it('accepts a pending result across a genuine same-account bearer refresh', async () => {
    const pending = deferred<Response>(); apiRequest.mockImplementation(() => pending.promise);
    vi.stubGlobal('fetch', vi.fn(async (url: string) => {
      if (String(url).endsWith('/api/v1/auth/refresh')) return response({ accessToken: 'fixture-vault-refreshed', refreshToken: 'fixture-vault-refreshed-again', expiresIn: 3600 }, 200);
      throw new Error('Unexpected fixture route');
    }));
    const guard = authService.captureSessionReadGuard();
    const p = props(); render(<FileToVaultDialog {...p} />); submit();
    await act(async () => { expect(await authService.refreshToken()).toBe(true); });
    expect(guard.sameRevision()).toBe(true); expect(guard.credentialsCurrent()).toBe(false);
    await act(async () => { pending.resolve(response(receipt())); await pending.promise; });
    expect(screen.getByTestId('ftv-result')).toBeTruthy();
    expect(p.onFiled).toHaveBeenCalledTimes(1); expect(p.fireToast).toHaveBeenCalledTimes(1);
  });

  it.each(['document', 'document project', 'shell project', 'shell round trip', 'account', 'organization', 'logout'] as const)(
    'does not publish an old result after changing %s', async transition => {
      const pending = deferred<Response>(); apiRequest.mockImplementation(() => pending.promise);
      const p = props(); const view = render(<FileToVaultDialog {...p} />); submit();
      if (transition === 'document') view.rerender(<FileToVaultDialog {...p} docId={OTHER} />);
      else if (transition === 'document project') view.rerender(<FileToVaultDialog {...p} programId={OTHER} />);
      else act(() => {
        if (transition === 'shell project' || transition === 'shell round trip') {
          publishShellProject({ id: OTHER });
          if (transition === 'shell round trip') publishShellProject({ id: PID });
        } else if (transition === 'logout') authService.endSession(null);
        else authService.setToken('fixture-vault-author-b', { id: transition === 'account' ? '8' : '7', organizationId: transition === 'organization' ? '2' : '1' }, 'fixture-refresh-b', 3600);
      });
      await act(async () => { pending.resolve(response(receipt())); await pending.promise; });
      expect(screen.queryByTestId('ftv-result')).toBeNull();
      expect(screen.queryByTestId('ftv-error')).toBeNull();
      expect(p.onFiled).not.toHaveBeenCalled(); expect(p.fireToast).not.toHaveBeenCalled();
      expect(window.C2C_VAULT_TARGET).toBeUndefined();
    },
  );

  it('does not publish an old rejection after changing the source document', async () => {
    const pending = deferred<Response>(); apiRequest.mockImplementation(() => pending.promise);
    const p = props(); const view = render(<FileToVaultDialog {...p} />); submit();
    view.rerender(<FileToVaultDialog {...p} docId={OTHER} />);
    await act(async () => { pending.reject(new Error('lost reply')); await pending.promise.catch(() => {}); });
    expect(screen.queryByTestId('ftv-error')).toBeNull(); expect(p.fireToast).not.toHaveBeenCalled();
  });

  it('retires a confirmed navigation after leaving and returning to the shell project', async () => {
    const p = props(); render(<FileToVaultDialog {...p} />); submit();
    await screen.findByTestId('ftv-result');
    const oldControl = screen.getByTestId('ftv-open-vault');
    act(() => { publishShellProject({ id: OTHER }); publishShellProject({ id: PID }); });
    fireEvent.click(oldControl);
    expect(p.onNav).not.toHaveBeenCalled(); expect(window.C2C_VAULT_TARGET).toBeUndefined();
  });

  it('posts once when the submit action is activated twice before the reply', async () => {
    const pending = deferred<Response>(); apiRequest.mockImplementation(() => pending.promise);
    const p = props(); render(<FileToVaultDialog {...p} />);
    act(() => { submit(); submit(); });
    expect(apiRequest).toHaveBeenCalledTimes(1);
    await act(async () => { pending.resolve(response(receipt())); await pending.promise; });
    expect(p.onFiled).toHaveBeenCalledTimes(1);
  });
});

// @vitest-environment jsdom
/**
 * DocumentWorkbench — File to vault.
 *
 * POST /api/authoring/docs/:docId/file-to-vault { format } (WM's route). What
 * is pinned: the dialog sends exactly that, renders the server's own result
 * (folder, SHA-256, vault id) and nothing composed locally, renders the
 * server's refusal as a refusal with nothing claimed, refuses honestly with
 * no program, and is disabled while the open section has unsaved changes
 * (the vault files the SAVED document).
 */
import React from 'react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { ApiRequestError } from '@/lib/queryClient';
import type { FireToast } from '../toast';

const apiRequest = vi.hoisted(() => vi.fn());
vi.mock('@/lib/queryClient', async (importOriginal) => ({
  ...(await importOriginal<typeof import('@/lib/queryClient')>()),
  apiRequest,
}));
vi.mock('@/services/portal/authService', async original => ({
  ...(await original<typeof import('@/services/portal/authService')>()),
  useAuth: () => ({ user: { displayName: 'Test Author', email: 'author@test.co' } }),
}));
vi.mock('../surfaces/AuthoringCollab', () => ({ AuthoringCollab: () => null }));
vi.mock('../surfaces/AuthoringFilingBar', () => ({ AuthoringFilingBar: () => null }));
vi.mock('../surfaces/AuthoringCreateExport', () => ({ AuthoringCreateExport: () => null }));
vi.mock('../surfaces/AuthoringPlaceIntoFiling', () => ({ AuthoringPlaceIntoFiling: () => null }));

const emptyRects = function () { return [] as unknown as DOMRectList; };
for (const proto of [Range.prototype, Element.prototype, Text.prototype] as unknown as Array<Record<string, unknown>>) {
  if (typeof proto.getClientRects !== 'function') proto.getClientRects = emptyRects;
  if (typeof proto.getBoundingClientRect !== 'function') {
    proto.getBoundingClientRect = function () {
      return { top: 0, left: 0, right: 0, bottom: 0, width: 0, height: 0, x: 0, y: 0 } as DOMRect;
    };
  }
}

import { DocumentAuthoring } from '../surfaces/DocumentAuthoring';
import { DocumentCanvas } from '../editor/DocumentCanvas';
import { FileToVaultDialog } from '../editor/FileToVaultDialog';
import { DocumentWorkbench } from '../editor/DocumentWorkbench';
import { authService } from '@/services/portal/authService';

const PID = '5ac45b38-a1d8-4a41-9488-fac39a57b852';
const DOC = 'dddddddd-dddd-4ddd-8ddd-dddddddddddd';
const SEC = 'ssssssss-ssss-4sss-8sss-ssssssssssss';
const ok = (payload: unknown, status = 200) => ({ ok: status < 400, status, json: async () => payload }) as Response;

const FILED = { success: true, data: { vaultDocumentId: 'c4411315-0dd8-4775-9377-d123b9f9d16d', folder: 'module-2', sha256: '44cf3a1bedc69fc402070838694cd33e02c9c51b0a08c5a0b06706e8ca839b4f', format: 'pdf', fileName: 'module-2-5.pdf', programId: PID, sealed: false } };

let fileToVault: () => Promise<Response> | Response;
function mockApi() {
  apiRequest.mockReset();
  apiRequest.mockImplementation(async (method: string, url: string) => {
    if (url.startsWith('/api/authoring/docs?')) {
      return ok({ documents: [{ id: DOC, title: 'Module 2.5 Clinical Overview', module: 'M2', product_code: null, status: 'draft', updated_at: null, section_count: 1 }] });
    }
    if (url.split('?')[0] === `/api/authoring/docs/${DOC}`) return ok({ success: true, document: { id: DOC, title: 'Module 2.5 Clinical Overview', module: 'M2', status: 'draft', provenance: null } });
    if (url.split('?')[0] === `/api/authoring/docs/${DOC}/sections`) {
      return ok({ sections: [{ id: SEC, doc_id: DOC, code: '2.5.1', title: 'Rationale', content: '<p>The product rationale.</p>', order_index: 0, comment_count: 0, revision_count: 0, citation_count: 0, updated_at: null }] });
    }
    if (method === 'POST' && url === `/api/authoring/docs/${DOC}/file-to-vault`) return fileToVault();
    if (url === `/api/c2c/projects/${PID}`) return ok({ id: PID, name: 'C2C-101', phase: 'planning' });
    if (url.startsWith('/api/c2c/documents/')) return ok({ success: false }, 404);
    return ok({ success: true, sources: [], revisions: [], comments: [] });
  });
}

const props = () => ({ surface: { id: 'document-authoring', label: 'Authoring' } as any, onAsk: vi.fn(), onNav: vi.fn(), segment: 'biotech' });

async function openDialog() {
  render(<DocumentAuthoring {...props()} />);
  await screen.findAllByText('Rationale');
  fireEvent.click(await screen.findByTestId('file-to-vault-open'));
  return screen.findByTestId('file-to-vault-dialog');
}

beforeEach(() => {
  (window as any).C2C_PROJECT = { id: PID, title: 'C2C-101' };
  fileToVault = () => ok(FILED, 201);
  mockApi();
});
afterEach(() => {
  cleanup();
  authService.endSession(null);
  delete (window as any).C2C_PROJECT;
  delete (window as any).C2C_VAULT_TARGET;
});

describe('DocumentWorkbench — File to vault', () => {
  it('explains separate rendition versions and explicit sequence replacement before filing', async () => {
    const dlg = await openDialog();
    const policy = within(dlg).getByTestId('ftv-version-policy');
    expect(policy.textContent).toContain('PDF and Word are versioned separately');
    expect(policy.textContent).toContain('earlier bytes are preserved');
    expect(policy.textContent).toContain('Existing sequence placements stay pinned');
    expect(policy.textContent).toContain('replace them explicitly');
    expect(apiRequest.mock.calls.some(([method]) => method === 'POST')).toBe(false);
  });

  it.each([
    ['1.0', null],
    ['3.0', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'],
  ])('shows the server-confirmed Vault version %s and its recorded predecessor', async (version, supersedesDocumentId) => {
    fileToVault = () => ok({ ...FILED, data: { ...FILED.data, version, supersedesDocumentId } }, 201);
    const dlg = await openDialog();
    fireEvent.click(within(dlg).getByTestId('ftv-submit'));
    const result = await within(dlg).findByTestId('ftv-result');
    expect(result.textContent).toContain(`Vault version ${version}.`);
    if (supersedesDocumentId) expect(result.textContent).toContain(`Supersedes Vault id ${supersedesDocumentId}.`);
    else expect(result.textContent).not.toContain('Supersedes');
    expect(apiRequest).toHaveBeenCalledWith('POST', `/api/authoring/docs/${DOC}/file-to-vault`, { format: 'pdf' });
  });

  it('shows the server legacy-family refusal without claiming a new version', async () => {
    const message = 'Earlier Authoring filings use retained legacy version labels. Review the existing Vault records before filing another version.';
    fileToVault = () => { throw new ApiRequestError(message, 409, { success: false, error: { code: 'AUTHORING_VAULT_LEGACY_VERSIONS' } }, 'AUTHORING_VAULT_LEGACY_VERSIONS'); };
    const dlg = await openDialog();
    fireEvent.click(within(dlg).getByTestId('ftv-submit'));
    expect((await within(dlg).findByTestId('ftv-error')).textContent).toBe(message);
    expect(within(dlg).queryByTestId('ftv-result')).toBeNull();
    expect(within(dlg).queryByTestId('ftv-open-vault')).toBeNull();
  });

  it('calls the route with the chosen format and renders the server’s folder, hash and id', async () => {
    fileToVault = () => ok({ ...FILED, data: { ...FILED.data, format: 'docx' } }, 201);
    const dlg = await openDialog();
    expect(dlg.getAttribute('aria-modal')).toBe('true');
    fireEvent.click(within(dlg).getByLabelText(/Word/));
    fireEvent.click(within(dlg).getByTestId('ftv-submit'));
    await waitFor(() => expect(apiRequest).toHaveBeenCalledWith('POST', `/api/authoring/docs/${DOC}/file-to-vault`, { format: 'docx' }));
    const result = await within(dlg).findByTestId('ftv-result');
    expect(result.textContent).toContain('under module-2');
    expect(result.textContent).toContain('Vault id c4411315-0dd8-4775-9377-d123b9f9d16d');
    expect(result.textContent).toContain('SHA-256 44cf3a1bedc69fc402070838694cd33e02c9c51b0a08c5a0b06706e8ca839b4f');
    // The receipt confirms the format requested by this filing.
    expect(result.textContent).toContain('Filed as DOCX');
    expect(within(dlg).queryByTestId('ftv-submit')).toBeNull();
  });

  it('says the Authoring approval carried, naming who reviewed and approved, as the server reported it (FD5 (c))', async () => {
    fileToVault = () => ok({ ...FILED, data: { ...FILED.data, sealed: true, approval: { carried: true, reviewedBy: 'Rae Reviewer', approvedBy: 'Abe Approver', canonicalId: 'x' } } }, 201);
    const dlg = await openDialog();
    fireEvent.click(within(dlg).getByTestId('ftv-submit'));
    const line = await within(dlg).findByTestId('ftv-approval');
    expect(line.textContent).toBe('The Authoring approval carried to this file (reviewed by Rae Reviewer, approved by Abe Approver). The Vault shows the version as approved.');
  });

  it('says the approval did not carry, with the server’s reason and what to do next', async () => {
    fileToVault = () => ok({ ...FILED, data: { ...FILED.data, approval: { carried: false, reason: 'It is not approved in Authoring (status: draft).' } } }, 201);
    const dlg = await openDialog();
    fireEvent.click(within(dlg).getByTestId('ftv-submit'));
    const line = await within(dlg).findByTestId('ftv-approval');
    expect(line.textContent).toBe('Not approved in the Vault: It is not approved in Authoring (status: draft). Review and approve this version in the Vault before it is transmitted.');
    expect(line.className).toBe('de-err');
  });

  it('claims no approval when the server reported none', async () => {
    const dlg = await openDialog();
    fireEvent.click(within(dlg).getByTestId('ftv-submit'));
